namespace Il2CppInterop.SourceGenerator.Tests.Generation;

public class InjectedClassTests : SourceGenerationTests
{
    [Test]
    public Task ClassWithNoMembers()
    {
        var testCode = """
            using Il2CppInterop.Common.Attributes;

            [InjectedType]
            public partial class Sample : Il2CppSystem.Object
            {
            }
            """;

        var expectedGeneratedCode = """
            // <auto-generated/>
            #nullable enable

            [global::Il2CppInterop.Common.Attributes.Il2CppType(typeof(Il2CppInternals))]
            public partial class Sample : global::Il2CppInterop.Common.IIl2CppType<Sample>
            {
                public Sample(global::Il2CppInterop.Common.ObjectPointer pointer) : base(pointer)
                {
                }

                nint global::Il2CppInterop.Common.IIl2CppType.ObjectClass => global::Il2CppInterop.Common.Il2CppType.GetClassPointer<Sample>();
            
                static Sample global::Il2CppInterop.Common.IIl2CppType<Sample>.UnboxNative(global::Il2CppInterop.Common.ObjectPointer pointer) => new Sample(pointer);

                static int global::Il2CppInterop.Common.IIl2CppType<Sample>.Size => nint.Size;
            
                static Sample? global::Il2CppInterop.Common.IIl2CppType<Sample>.ReadFromSpan(global::System.ReadOnlySpan<byte> span)
                {
                    return global::Il2CppInterop.Common.Il2CppType.ReadReference<Sample>(span);
                }

                static void global::Il2CppInterop.Common.IIl2CppType<Sample>.WriteToSpan(Sample? value, global::System.Span<byte> span)
                {
                    global::Il2CppInterop.Common.Il2CppType.WriteReference(value, span);
                }
            
                static Sample()
                {
                    global::System.Runtime.CompilerServices.RuntimeHelpers.RunClassConstructor(typeof(Il2CppInternals).TypeHandle);
                }
            }

            file static class Il2CppInternals
            {
            
                static Il2CppInternals()
                {
            #pragma warning disable IL2026 // Members annotated with 'RequiresUnreferencedCodeAttribute' require dynamic access otherwise can break functionality when trimming application code
            #pragma warning disable IL3050 // Calling members annotated with 'RequiresDynamicCodeAttribute' may break functionality when AOT compiling.
                    global::Il2CppInterop.Runtime.Injection.TypeInjector.RegisterTypeInIl2Cpp<Sample>();
            #pragma warning restore IL3050 // Calling members annotated with 'RequiresDynamicCodeAttribute' may break functionality when AOT compiling.
            #pragma warning restore IL2026 // Members annotated with 'RequiresUnreferencedCodeAttribute' require dynamic access otherwise can break functionality when trimming application code
                }
            }

            """;

        return TestGeneration(testCode, "Sample.g.cs", expectedGeneratedCode);
    }

    [Test]
    public Task ClassWithNullableManagedField()
    {
        var testCode = """
            #nullable enable
            using Il2CppInterop.Common.Attributes;

            [InjectedType]
            public partial class Sample : Il2CppSystem.Object
            {
                [ManagedField]
                public partial System.Collections.Generic.List<string>? Names { get; set; }
            }
            """;

        // The implementation is in a nullable-disabled context, or its type without the annotation makes the compiler report CS9256.
        Context.CompilerDiagnostics = Microsoft.CodeAnalysis.Testing.CompilerDiagnostics.Warnings;
        Context.DisabledDiagnostics.Add("CS1591"); // Missing XML comment

        var expectedGeneratedCode = """
            // <auto-generated/>
            #nullable enable

            [global::Il2CppInterop.Common.Attributes.Il2CppType(typeof(Il2CppInternals))]
            public partial class Sample : global::Il2CppInterop.Common.IIl2CppType<Sample>
            {
                [global::Il2CppInterop.Common.Attributes.Il2CppField(Name = nameof(Names))]
                private global::Il2CppSystem.IntPtr Names__BackingField
                {
                    get => global::Il2CppInterop.Runtime.FieldAccess.GetInstanceFieldValue<global::Il2CppSystem.IntPtr>(this, Il2CppInternals.FieldOffset_0);
                    set => global::Il2CppInterop.Runtime.FieldAccess.SetInstanceFieldValue(this, Il2CppInternals.FieldOffset_0, value);
                }

                #nullable disable
                public partial global::System.Collections.Generic.List<string> Names
                {
                    get => global::Il2CppInterop.Runtime.FieldAccess.GCHandleGetTarget(global::Il2CppInterop.Runtime.FieldAccess.GCHandleFromIntPtr<global::System.Collections.Generic.List<string>>(Names__BackingField));
                    set
                    {
                        global::Il2CppInterop.Runtime.FieldAccess.GCHandleFromIntPtr<global::System.Collections.Generic.List<string>>(Names__BackingField).Dispose();
                        Names__BackingField = global::Il2CppInterop.Runtime.FieldAccess.GCHandleToIntPtr(new global::System.Runtime.InteropServices.GCHandle<global::System.Collections.Generic.List<string>>(value));
                    }
                }
                #nullable enable

                public Sample(global::Il2CppInterop.Common.ObjectPointer pointer) : base(pointer)
                {
                }

                [global::Il2CppInterop.Common.Attributes.Il2CppMethod(Name = "Finalize")]
                public override void Il2CppFinalize()
                {
                    // This disposal happens when the object is collected by the Il2Cpp GC instead of the managed GC.
                    // That ensures that the referenced value is kept alive as long as the Il2Cpp object is alive, even if the managed wrapper gets collected.
                    // In theory, the managed wrapper could be collected and recreated multiple times during the lifetime of the Il2Cpp object,
                    // so this ensures that the managed fields are not disposed prematurely.
                    try
                    {
                        Names = null!;
                    }
                    catch (global::System.Exception ex)
                    {
                        LogErrorIl2CppFinalize(ex);
                    }
                    finally
                    {
                        base.Il2CppFinalize(); // Must call base method
                    }
                }

                partial void LogErrorIl2CppFinalize(global::System.Exception exception);

                nint global::Il2CppInterop.Common.IIl2CppType.ObjectClass => global::Il2CppInterop.Common.Il2CppType.GetClassPointer<Sample>();

                static Sample global::Il2CppInterop.Common.IIl2CppType<Sample>.UnboxNative(global::Il2CppInterop.Common.ObjectPointer pointer) => new Sample(pointer);

                static int global::Il2CppInterop.Common.IIl2CppType<Sample>.Size => nint.Size;

                static Sample? global::Il2CppInterop.Common.IIl2CppType<Sample>.ReadFromSpan(global::System.ReadOnlySpan<byte> span)
                {
                    return global::Il2CppInterop.Common.Il2CppType.ReadReference<Sample>(span);
                }

                static void global::Il2CppInterop.Common.IIl2CppType<Sample>.WriteToSpan(Sample? value, global::System.Span<byte> span)
                {
                    global::Il2CppInterop.Common.Il2CppType.WriteReference(value, span);
                }

                static Sample()
                {
                    global::System.Runtime.CompilerServices.RuntimeHelpers.RunClassConstructor(typeof(Il2CppInternals).TypeHandle);
                }
            }

            file static class Il2CppInternals
            {
                public static readonly int FieldOffset_0; // Names

                static Il2CppInternals()
                {
            #pragma warning disable IL2026 // Members annotated with 'RequiresUnreferencedCodeAttribute' require dynamic access otherwise can break functionality when trimming application code
            #pragma warning disable IL3050 // Calling members annotated with 'RequiresDynamicCodeAttribute' may break functionality when AOT compiling.
                    global::Il2CppInterop.Runtime.Injection.TypeInjector.RegisterTypeInIl2Cpp<Sample>();
            #pragma warning restore IL3050 // Calling members annotated with 'RequiresDynamicCodeAttribute' may break functionality when AOT compiling.
            #pragma warning restore IL2026 // Members annotated with 'RequiresUnreferencedCodeAttribute' require dynamic access otherwise can break functionality when trimming application code
                    FieldOffset_0 = global::Il2CppInterop.Runtime.FieldAccess.GetFieldOffset(global::Il2CppInterop.Runtime.FieldAccess.GetFieldInfo(global::Il2CppInterop.Common.Il2CppType.GetClassPointer<Sample>(), "Names"));
                }
            }

            """;

        return TestGeneration(testCode, "Sample.g.cs", expectedGeneratedCode);
    }
}
